import { createApp } from 'vue'
import Vant from 'vant'
import 'vant/lib/index.css'

// Arco 全局基础样式：CSS 变量（含暗黑主题）、图标基础样式、过渡动画
import '@arco-design/web-vue/es/style/index.css'
// Arco 组件样式（按需，css.js 会自动引入依赖的子组件样式）
import '@arco-design/web-vue/es/modal/style/css.js'
import '@arco-design/web-vue/es/select/style/css.js'
import '@arco-design/web-vue/es/input/style/css.js'
import '@arco-design/web-vue/es/upload/style/css.js'
import '@arco-design/web-vue/es/button/style/css.js'
import '@arco-design/web-vue/es/message/style/css.js'
import '@arco-design/web-vue/es/skeleton/style/css.js'
// Arco 组件（按需）
import { Modal, Select, Option, Input, Upload, Button, Skeleton, SkeletonShape } from '@arco-design/web-vue'
// Arco 图标（按需）
import { IconPlus, IconImage, IconLink } from '@arco-design/web-vue/es/icon'

import App from './App.vue'

// Arco 暗黑主题
document.body.setAttribute('arco-theme', 'dark')

const app = createApp(App)
app.use(Vant)
app.component('AModal', Modal)
app.component('ASelect', Select)
app.component('AOption', Option)
app.component('AInput', Input)
app.component('AUpload', Upload)
app.component('AButton', Button)
app.component('ASkeleton', Skeleton)
app.component('ASkeletonShape', SkeletonShape)
app.component('IconPlus', IconPlus)
app.component('IconImage', IconImage)
app.component('IconLink', IconLink)
app.mount('#app')
